/**
 * The npm publishing workflow: the second file this generator writes into
 * `.github/workflows`, and the only one that is not a gate.
 *
 * It is generated by `fjs ci` rather than by a command of its own. The two
 * workflows share every pin they name — the runner image, the Node version, the
 * pinned actions — and `../README.md`'s drift check covers whatever `fjs ci`
 * writes for free, so a separate command would have to be chained into
 * `ci-update` to get back to where this already is.
 *
 * @module
 *
 * @import { GitHubAction, Job, MetaStep } from '../common/types.ts'
 */

import { node, typescript } from '../config/module.f.mjs'
import { install, test, ubuntuArm, uses } from '../common/module.f.mjs'

/** Where the pipeline writes the workflow below. */
export const npmPublishPath = /** @type {const} */ ('.github/workflows/npm-publish.yml')

/**
 * The branch a publish follows. The version in `package.json` is the single
 * source of truth for what gets published, and it becomes real when it reaches
 * the default branch — so this is the one trigger, and it is a `push` rather
 * than a `pull_request`: a fork's pull request must never reach a step holding
 * the registry's trust.
 */
export const publishBranch = /** @type {const} */ ('main')

export const npmPublishJobId = /** @type {const} */ ('publish-npm')

/**
 * The registry `setup-node` writes into the job's `.npmrc`. Without it npm
 * publishes to whatever `publishConfig` or the runner's default names, which
 * for a job whose whole purpose is one registry is a thing that can be wrong
 * silently.
 */
const registry = /** @type {const} */ ('https://registry.npmjs.org/')

/**
 * No token. `id-token: write` below lets npm's trusted publishing exchange the
 * runner's OIDC token for the credential, so the workflow holds no secret at
 * all and a fork cannot borrow one.
 *
 * `--provenance` is what makes that exchange worth having: npm records the
 * workflow, the commit and the repository that produced the tarball, and a
 * consumer can check the published package against them.
 *
 * @type {readonly MetaStep[]}
 */
const publishSteps = [
    install(uses('actions/setup-node', {
        'node-version': node.default,
        'registry-url': registry,
    })),
    // The compiler `prepack` runs. It is not a dependency of the package, so
    // `npm ci` below does not bring one, and this is the only job in either
    // workflow that needs one without having a flake to take it from — a
    // publish wants the `.npmrc` `setup-node` writes, and the shells know
    // nothing about a registry.
    //
    // Nothing checks the version afterwards, unlike the shells that provide
    // it: this step names the release it installs, so a check could only
    // restate the line above it.
    install({ run: `npm install -g typescript@${typescript.version}` }),
    // `prepack` emits the declarations the package ships and type-checks them,
    // so the install is not optional the way it would be for a package that
    // publishes its sources unchanged — `@types/node` is what the compiler
    // above resolves against.
    test({ run: 'npm ci' }),
    // Most pushes to the branch do not move `package.json`'s version, and npm
    // answers a republish of an existing version with a 403. That is the
    // expected outcome here rather than a failure, and it is the reason for
    // `continue-on-error` — which is also why this step swallows a real
    // failure, an authentication or provenance error, just as quietly.
    // `../todo/publish-only-a-new-version.md` owns making the two
    // distinguishable.
    test({ run: 'npm publish --provenance', 'continue-on-error': true }),
]

/**
 * Built through the shared assembler, so the checkout lands where every other
 * job has it — after the tool installs, before the commands that read the
 * repository. It is a plain checkout: `npm publish --provenance` reads the
 * commit it is attesting from the runner's own environment rather than from
 * git, so nothing here needs history.
 *
 * @type {Job}
 */
export const npmPublishJob = ubuntuArm(publishSteps)

/**
 * `contents: read` and nothing more on the repository — a publish reads the
 * tree and writes nowhere in it. `id-token: write` is the one addition, and it
 * is what the provenance step above spends.
 *
 * @type {GitHubAction}
 */
export const npmPublishWorkflow = {
    name: 'npm publish',
    on: {
        push: { branches: [publishBranch] },
    },
    permissions: {
        contents: 'read',
        'id-token': 'write',
    },
    jobs: {
        [npmPublishJobId]: npmPublishJob,
    },
}
